            ['kod' => 'TFD-141', 'bolum' => 'Torna', 'faaliyet' => 'Elektrik çarpması', 'tehlike' => 'Enerji kesilmeden yaralıya temas', 'risk' => 'Kurtarıcının çarpılması ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Enerjiyi güvenli noktadan ayırın, 112\'ye haber verin. Canlı bölüme veya yaralıya doğrudan dokunmayın. Güvenli ortam sağlanınca eğitimli ilk yardımcı müdahale etsin; arıza giderilip test edilmeden makine çalıştırılmasın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 40.0],
            ['kod' => 'TFD-142', 'bolum' => 'Torna', 'faaliyet' => 'Yangın veya duman', 'tehlike' => 'Uygunsuz söndürme ve gecikmiş tahliye', 'risk' => 'Yanık, duman maruziyeti ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Alarm verin, güvenliyse enerjiyi ayırın ve alanı boşaltın. Yağ, elektrik ve varsa yanıcı metal için uygun müdahale yöntemini önceden belirleyin. Eğitimli ekip güvenli sınır dışında müdahale etmesin; 112\'ye ekipman/malzeme bilgisini iletin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-143', 'bolum' => 'Torna', 'faaliyet' => 'Sıvı sıçraması veya dökülmesi', 'tehlike' => 'Kimyasal temas ve kaygan alana kontrolsüz giriş', 'risk' => 'Göz/cilt hasarı ve düşme', 'mevcut_onlem' => NULL, 'oneri' => 'GBF\'ye uygun göz/cilt yıkama erişimi sağlayın. Maruziyette GBF ilk yardım bilgisini ve sağlık yönlendirmesini izleyin. Alanı ayırıp uygun emiciyle eğitimli personele temizletin; makine kaçağı giderilmeden normal kullanıma dönmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'TFD-144', 'bolum' => 'Torna', 'faaliyet' => 'Kesinti, deprem ve tahliye', 'tehlike' => 'Beklenmeyen yeniden başlatma veya engelli kaçış', 'risk' => 'Çarpılma, ezilme ve tahliye gecikmesi', 'mevcut_onlem' => NULL, 'oneri' => 'Güvenli uzaklaşmayı ve açık kaçış yolunu sağlayın. Kesinti/deprem sonrası bağlama, enerji ve yapısal hasarı yetkili ekip kontrol etsin. Enerji dönüşü tek başına çalıştırma oluşturmasın; sayım ve yeniden başlatma sorumlusunu belirleyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
        ]],
