            ['kod' => 'MAK-174', 'bolum' => 'Acil durumlar', 'faaliyet' => 'Sıcak eriyik kazası', 'tehlike' => 'Uygunsuz ilk müdahale', 'risk' => 'Yanığın ağırlaşması', 'mevcut_onlem' => NULL, 'oneri' => 'Sıcak yüzey/eriyik kazası için ilkyardım organizasyonunu kurun. Eğitimli ilkyardımcı ve acil yardım erişimini sağlayın; yapışan plastiği zorla sökme gibi hatalı müdahaleleri önleyen eğitim verin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); İşyeri talimatı / risk değerlendirmesi / acil durum planı', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 15.0],
            ['kod' => 'MAK-175', 'bolum' => 'Acil durumlar', 'faaliyet' => 'Deprem', 'tehlike' => 'Raf, tüp ve ekipmanın devrilmesi', 'risk' => 'Ezilme ve çıkışın kapanması', 'mevcut_onlem' => NULL, 'oneri' => 'Raf/tüp/ekipman sabitlemesini kontrol edin. Güvenli toplanma ve sayım düzeni kurun; deprem sonrası enerji ve yapısal güvenlik kontrolü bitmeden üretime dönmeyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); İşyeri talimatı / risk değerlendirmesi / acil durum planı', 'olasilik' => 3.0, 'frekans' => 0.5, 'siddet' => 40.0],
            ['kod' => 'MAK-176', 'bolum' => 'Acil durumlar', 'faaliyet' => 'Haberleşme ve ekip', 'tehlike' => 'Acil durumda kimin ne yapacağının bilinmemesi', 'risk' => 'Müdahalenin gecikmesi', 'mevcut_onlem' => NULL, 'oneri' => 'Vardiyalara uygun acil görevleri ve iletişim listesini belirleyin. Ekipman erişimini ve çağrı yöntemini deneyin; tatbikat eksiklerini sorumlu ve terminle kapatın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); İşyeri talimatı / risk değerlendirmesi / acil durum planı', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 40.0],
