        'atolye_cnc_isleme_merkezi' => ['Atölye – CNC işleme merkezi', [
            ['kod' => 'CNC-001', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Otomatik talaşlı imalat', 'tehlike' => 'Kesim bölgesinin açık olması veya muhafazanın yetersizliği', 'risk' => 'Dönen takıma temas, parça fırlaması, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'İmalatı, tehlike bölgesine erişimi ve fırlayan parçayı engelleyen üretici tasarımına uygun kapalı kabin içinde yapın. Açıklıkları ve servis kapaklarını kontrol edin. Eksik muhafaza tamamlanıp işlevi doğrulanmadan üretime izin vermeyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-002', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Kapı açma ve kapatma', 'tehlike' => 'Kapı emniyet kilidinin devre dışı bırakılması', 'risk' => 'Dönen takıma temas, uzuv kaybı', 'mevcut_onlem' => NULL, 'oneri' => 'Kapı anahtarı ve kilitleme düzenini üreticiye uygun, kolay aldatılamayan yapıda tutun. Yedek aktüatörle veya yazılımla baypası önleyin. Yetkili personel tüm çalışma modlarında güvenli test yapsın. Arızada makineyi kullanım dışı bırakın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-003', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Mil duruşunu bekleme', 'tehlike' => 'Tehlikeli hareket bitmeden kapının açılabilmesi', 'risk' => 'Takıma takılma ve ölümcül yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Erişim süresi ile en olumsuz mil durma süresini karşılaştırın. Gerekiyorsa tehlike sona erene kadar koruyucu kilitlemesi kullanın. Sabit gecikmeye güvenmeden üretici tasarımını ve güvenli duruş algılamasını yetkin kişiyle doğrulayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-004', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Kabin penceresinden izleme', 'tehlike' => 'Çatlak veya uygun olmayan koruyucu pencere', 'risk' => 'Takım ya da parça darbesiyle ağır yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Pencerenin darbe dayanımını üretici şartına göre kontrol edin. Çatlama, çizilme, kimyasal bozulma ve yaşlanmayı izleyin. Sıradan cam veya uygunluğu bilinmeyen levha kullanmayın. Hasarlı pencereyi üreticinin tarif ettiği bileşenle değiştirin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-005', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Emniyet devrelerinin işletilmesi', 'tehlike' => 'Tek arıza veya uygunsuz devre değişikliği', 'risk' => 'Emniyet işlevinin kaybı, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Kapı, güvenli duruş ve yeniden başlatmayı önleme işlevlerini tanımlayın. Gerekli güvenlik performansını makineye özgü değerlendirin. Değişiklikleri yetkin tasarımcıya yaptırın; arıza davranışı dahil doğrulamadan sonra devreye alın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-006', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Acil durdurma kullanımı', 'tehlike' => 'Durdurma butonunun erişilemez veya işlevsiz olması', 'risk' => 'Tehlikeli hareketin sürmesi, ağır yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Operatör ve müdahale noktalarından erişilebilen acil durdurma düzenini kontrol edin. Tüm ilişkili tehlikeli hareketlerin güvenli tepki verdiğini test edin. Butonun çözülmesi tek başına yeniden başlatmasın. Acil durdurmayı enerji izolasyonu yerine kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-007', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Enerji kesintisi sonrası çalışma', 'tehlike' => 'Enerji geri geldiğinde kendiliğinden hareket', 'risk' => 'Sıkışma, ezilme, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Elektrik veya hava basıncı geri geldiğinde otomatik çevrim başlamasını önleyin. Güvenli reset ve ayrı başlatma işlemi tanımlayın. Testi tehlike alanı boşken yetkili personelle yapın; kesinti sonrası parça ve takım konumunu kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'CNC-008', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Ayar ve jog hareketi', 'tehlike' => 'Açık kapıda kontrolsüz eksen veya mil hareketi', 'risk' => 'Ezilme, kesilme, uzuv kaybı', 'mevcut_onlem' => NULL, 'oneri' => 'Sadece üreticinin öngördüğü ayar modunu kullanın. Gerekli azaltılmış hız, basılı tutarak kumanda ve etkinleştirme tertibatını güvenlik fonksiyonu olarak doğrulayın. Anahtarı yetkili kişide tutun. Kapı kilidini iptal ederek ayar yapmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 6.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'CNC-009', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Alanı görmeden başlatma', 'tehlike' => 'Kabin veya servis alanında kişinin kalması', 'risk' => 'Ezilme ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'İçine girilebilen kabinde kişisel kilitleme ve güvenli çıkış düzenini değerlendirin. Reset noktasından alanın görülebilmesini sağlayın; kör alan varsa ek teknik önlem kurun. Reset tehlikeli hareketi başlatmasın. Kişi içerideyken dışarıdan başlatmayı önleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'CNC-010', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Uzaktan bağlantı ve program gönderme', 'tehlike' => 'Yetkisiz komut veya parametre değişikliği', 'risk' => 'Beklenmeyen hareket ve çarpışma', 'mevcut_onlem' => NULL, 'oneri' => 'Uzaktan erişimi adlandırılmış yetkilerle ve kontrollü oturumla sınırlandırın. Bakım sırasında yerel izolasyonu koruyun. Emniyet parametrelerini erişim kontrolüne alın. Program aktarımı çevrimi kendiliğinden başlatmasın; değişikliği operatör doğrulasın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'CNC-011', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Mengene ve fikstür bağlama', 'tehlike' => 'Yetersiz sıkma, gevşek bağlantı veya yanlış oturma', 'risk' => 'İş parçası fırlaması, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Parça geometrisi, kesme kuvveti ve bağlantı elemanına uygun bağlama planı hazırlayın. Temas yüzeylerini temizleyin; üreticinin sıkma torkunu uygulayın. Kısa kavrama ve uygunsuz ara parçaları önleyin. İlk parçada bağlama doğrulaması yapın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-012', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Hidrolik veya pnömatik sıkma varsa', 'tehlike' => 'Basınç kaybında parçanın serbest kalması', 'risk' => 'Parça fırlaması, ağır yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Sıkma durumunun ve gerekli basıncın güvenli izlenmesini doğrulayın. Basınç kaybında güvenli tepkiyi üretici tasarımına göre sağlayın. Basıncı yalnız göstergeden okumayı yeterli saymayın; enerji kaybında tutma davranışını güvenli test edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 4413 / ISO 4414; üretici basınç devresi', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-013', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'İnce veya düzensiz parça işleme', 'tehlike' => 'Yetersiz destek ve kesme sırasında deformasyon', 'risk' => 'Parçanın kopması, takım kırılması', 'mevcut_onlem' => NULL, 'oneri' => 'İnce cidarlı veya uzun parçaya uygun destek ve fikstür tasarlayın. Kesme yükünü ve tutulan alanı doğrulayın. Tasarım dışı puntalama veya gelişigüzel takoz kullanmayın; deneme kesimini kapalı kabinde kontrollü parametrelerle yapın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'CNC-014', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Takım tutucu ve çekme saplaması seçimi', 'tehlike' => 'Uyumsuz, hasarlı veya gevşek tutucu', 'risk' => 'Takımın milden ayrılması, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Mil koniği, tutucu ve çekme saplamasını üretici spesifikasyonuyla eşleştirin. Temizliği, aşınmayı, torku ve sıkma mekanizmasını kontrol edin. Doğru çekme kuvvetini üretici yöntemiyle doğrulayın; uygunsuz takımı karantinaya alın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-015', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Yüksek devirde işleme', 'tehlike' => 'Takım hız sınırının aşılması veya balanssızlık', 'risk' => 'Takım parçalanması ve fırlama', 'mevcut_onlem' => NULL, 'oneri' => 'Kesici, tutucu ve bağlantı grubunun en düşük izin verilen hızını esas alın. Takım boyu ve balans şartlarını doğrulayın. Program devir sınırlarını tanımlayın. Titreşim veya anormal ses görüldüğünde çevrimi durdurup nedeni giderin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'CNC-016', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Kesici takım ömrü yönetimi', 'tehlike' => 'Aşınmış veya çatlak takımın kırılması', 'risk' => 'Kesici parçalarının fırlaması, yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Takım ömrü ve aşınma sınırlarını proses bazında belirleyin. Kesiciyi güvenli duruşta kontrol edin. Uygun kesme parametresi ve soğutma sağlayın. Kırık takım algılama varsa işlevini kontrol edin; algılamayı kabin muhafazası yerine kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'CNC-017', 'bolum' => 'CNC işleme merkezi', 'faaliyet' => 'Manuel takım takma ve çıkarma', 'tehlike' => 'Keskin veya ağır takımın ele düşmesi', 'risk' => 'Kesilme, ezilme, ayak yaralanması', 'mevcut_onlem' => NULL, 'oneri' => 'Milin güvenli durduğunu ve hareketin önlendiğini doğrulayın. Ağır takımlar için yardımcı taşıma düzeneği kullanın. Takımı kontrollü kavrayın; uygun kesilmeye dayanıklı eldiveni yalnız hareketsiz takım elleçlerken kullanın. Dönen takım yakınında eldiven kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I (makineyle ilişkili kısım); ISO 16090-1:2022; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 7.0],
