            ['kod' => 'TFD-145', 'bolum' => 'Dikey freze', 'faaliyet' => 'Kaptırma veya sıkışma', 'tehlike' => 'Kurtarma sırasında hareketin devam etmesi', 'risk' => 'İkincil yaralanma ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Acil durdurmayı kullanın ve enerjiyi güvenle ayırın. 112\'yi arayın; sıkışmış kişiyi rastgele ters hareket vererek çıkarmaya çalışmayın. Teknik kurtarma ve ilk yardım ekibini koordine edin; yük ve depolanmış enerji kontrol edilsin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-146', 'bolum' => 'Dikey freze', 'faaliyet' => 'Takım veya parça fırlaması', 'tehlike' => 'Hasarlı tezgâhta üretime devam edilmesi', 'risk' => 'İkinci fırlama ve ağır yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Çalışmayı durdurun, alanı ayırın ve yaralıya eğitimli ilk yardımcı aracılığıyla destek sağlayın. Bağlama, takım ve muhafazayı yetkin ekip incelemeden yeniden başlatmayın. Olay nedenini kaydedip ilgili DÖF\'leri tamamlayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-147', 'bolum' => 'Dikey freze', 'faaliyet' => 'Elektrik çarpması', 'tehlike' => 'Enerji kesilmeden yaralıya temas', 'risk' => 'Kurtarıcının çarpılması ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Enerjiyi güvenli noktadan ayırın, 112\'ye haber verin. Canlı bölüme veya yaralıya doğrudan dokunmayın. Güvenli ortam sağlanınca eğitimli ilk yardımcı müdahale etsin; arıza giderilip test edilmeden makine çalıştırılmasın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 40.0],
            ['kod' => 'TFD-148', 'bolum' => 'Dikey freze', 'faaliyet' => 'Yangın veya duman', 'tehlike' => 'Uygunsuz söndürme ve gecikmiş tahliye', 'risk' => 'Yanık, duman maruziyeti ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Alarm verin, güvenliyse enerjiyi ayırın ve alanı boşaltın. Yağ, elektrik ve varsa yanıcı metal için uygun müdahale yöntemini önceden belirleyin. Eğitimli ekip güvenli sınır dışında müdahale etmesin; 112\'ye ekipman/malzeme bilgisini iletin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-149', 'bolum' => 'Dikey freze', 'faaliyet' => 'Sıvı sıçraması veya dökülmesi', 'tehlike' => 'Kimyasal temas ve kaygan alana kontrolsüz giriş', 'risk' => 'Göz/cilt hasarı ve düşme', 'mevcut_onlem' => NULL, 'oneri' => 'GBF\'ye uygun göz/cilt yıkama erişimi sağlayın. Maruziyette GBF ilk yardım bilgisini ve sağlık yönlendirmesini izleyin. Alanı ayırıp uygun emiciyle eğitimli personele temizletin; makine kaçağı giderilmeden normal kullanıma dönmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'TFD-150', 'bolum' => 'Dikey freze', 'faaliyet' => 'Kesinti, deprem ve tahliye', 'tehlike' => 'Beklenmeyen yeniden başlatma veya engelli kaçış', 'risk' => 'Çarpılma, ezilme ve tahliye gecikmesi', 'mevcut_onlem' => NULL, 'oneri' => 'Güvenli uzaklaşmayı ve açık kaçış yolunu sağlayın. Kesinti/deprem sonrası bağlama, enerji ve yapısal hasarı yetkili ekip kontrol etsin. Enerji dönüşü tek başına çalıştırma oluşturmasın; sayım ve yeniden başlatma sorumlusunu belirleyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
        ]],
        'ekipman_trafo' => ['Ekipman – Trafo (OG/AG)', [
            ['kod' => 'TFD-081', 'bolum' => 'Trafo', 'faaliyet' => 'Trafo merkezine erişim', 'tehlike' => 'Yetkisiz kişinin gerilimli bölgeye girmesi', 'risk' => 'Elektrik çarpması, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Kapı, çevre çiti ve hücre erişimini kilitli ve kontrollü tutun. Yetki listesi ve anahtar yönetimi oluşturun; tehlike işaretlerini görünür yerleştirin. Ziyaretçi/temizlik personeli için refakat ve sınırlar tanımlayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 6.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-082', 'bolum' => 'Trafo', 'faaliyet' => 'İşletme sorumluluğu', 'tehlike' => 'Yetki ve teknik sorumlulukların tanımsız olması', 'risk' => 'Yanlış müdahale, ölümcül kaza', 'mevcut_onlem' => NULL, 'oneri' => 'YG tesisinin teknik sorumluluğunu mevzuata uygun elektrik mühendisiyle tanımlayın. İşletme, manevra, bakım ve kontrol yetkilerini yazılı ayırın. İlgili personelin eğitim/belge kapsamını doğrulayın; genel İSG eğitimi elektrik yetkisi sayılmasın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-083', 'bolum' => 'Trafo', 'faaliyet' => 'Tesis kimliğini belirleme', 'tehlike' => 'Güncel olmayan tek hat şeması ve etiket', 'risk' => 'Yanlış hücrede çalışma veya yanlış enerji verme', 'mevcut_onlem' => NULL, 'oneri' => 'Tek hat şemasını gerçek tesisle eşleştirin; hücre, kablo, trafo ve kaynak etiketlerini tutarlı yapın. Revizyonları yetkili mühendis onaylasın. İş emrinde ekipman kimliğini sahada çift kontrol ederek doğrulayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-084', 'bolum' => 'Trafo', 'faaliyet' => 'Çalışma izni düzenleme', 'tehlike' => 'İş sınırının ve enerji durumunun belirsizliği', 'risk' => 'Gerilimli bölüme temas ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'İşe özgü çalışma izni, risk değerlendirmesi ve sorumlu kişi belirleyin. İş alanı, enerji kaynakları, komşu canlı bölümler ve devreye alma koşulları yazılı olsun. Dağıtım kuruluşu ve yükleniciyle kesinti/teslim sınırlarını koordine edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-085', 'bolum' => 'Trafo', 'faaliyet' => 'Gerilimsiz çalışma hazırlığı', 'tehlike' => 'Tüm kaynaklardan ayırmama ve yeniden enerji verme', 'risk' => 'Elektrik çarpması, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Esas yöntem gerilimsiz çalışmadır. Yetkili ekip onaylı tesis prosedürüyle tüm kaynaklardan ayırmayı, yeniden enerjilenmeyi önlemeyi, gerilimsizliği doğrulamayı ve gerekli topraklama/kısa devrelemeyi sağlasın; komşu canlı kısımlara karşı koruma kursun. Doğrulama olmadan işe başlanmasın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 6.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-086', 'bolum' => 'Trafo', 'faaliyet' => 'Geri besleme kaynakları', 'tehlike' => 'Jeneratör, GES, UPS veya ikinci trafodan enerji gelmesi', 'risk' => 'Gerilimli kabul edilmeyen hatta ölümcül temas', 'mevcut_onlem' => NULL, 'oneri' => 'AG ve OG tarafındaki tüm olası beslemeleri tek hat şemasında belirleyin. Otomatik transfer, jeneratör, GES ve paralel bağlantıyı işe özgü izolasyona dahil edin. Sadece OG kesicisini açmayı yeterli saymayın; geri besleme yokluğu doğrulansın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-087', 'bolum' => 'Trafo', 'faaliyet' => 'Gerilimsizlik doğrulaması', 'tehlike' => 'Yanlış sınıfta veya arızalı dedektör kullanılması', 'risk' => 'Canlı devrede çalışma ve ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Gerilim seviyesine ve sisteme uygun doğrulama cihazını yetkili kişi kullansın. Cihazın uygunluğu, kontrol durumu ve işlem öncesi/sonrası işlev doğrulaması tesis prosedüründe tanımlansın. Sadece panel göstergesi veya SCADA durumuna güvenmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-088', 'bolum' => 'Trafo', 'faaliyet' => 'Topraklama ve kısa devreleme', 'tehlike' => 'Uygunsuz donanım veya eksik uygulama', 'risk' => 'İndüksiyon/yanlış enerji vermede ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Gereken geçici topraklama ve kısa devreleme noktalarını projeye göre belirleyin. Donanımın kısa devre dayanımı ve gerilim sınıfı uygun olsun. Uygulamayı yalnız yetkili ekip, gerilimsizlik doğrulanmış tesis prosedürüyle yapsın; takılı elemanları kayıtla takip edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-089', 'bolum' => 'Trafo', 'faaliyet' => 'Komşu canlı hücre yakınında çalışma', 'tehlike' => 'Güvenli mesafenin ihlali', 'risk' => 'Ark veya doğrudan temasla ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Gerilim düzeyine göre mevzuat/proje esaslı yaklaşma ve çalışma sınırlarını belirleyin. Komşu kısımları uygun bariyer ve işaretlemeyle ayırın; gerekirse onları da enerjisiz bırakın. Tek bir genel mesafeyi tüm tesislere uygulamayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-090', 'bolum' => 'Trafo', 'faaliyet' => 'OG manevrası', 'tehlike' => 'Yanlış sıra veya uygunsuz cihazla yük açma', 'risk' => 'Ark patlaması, çoklu ağır yaralanma', 'mevcut_onlem' => NULL, 'oneri' => 'Manevrayı yetkili kişilerin uygulayacağı tesis ve cihaz tipine özgü onaylı programa bağlayın. Kesici/ayırıcı/yük ayırıcısı işlevlerini ve kilitlemelerini doğrulayın. Cihazın kesme kapasitesi dışında işlem yaptırmayın; uzaktan manevra olanağını değerlendirin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-091', 'bolum' => 'Trafo', 'faaliyet' => 'Ark tehlikesi değerlendirmesi', 'tehlike' => 'Ark enerjisine uygun olmayan çalışma düzeni', 'risk' => 'Ağır yanık, basınç yaralanması, ölüm', 'mevcut_onlem' => NULL, 'oneri' => 'Kısa devre seviyesi, koruma açma süresi ve çalışma konumuna göre ark riskini yetkin mühendis değerlendirsin. Enerjisiz çalışma ve uzaktan işletmeyi önceliklendirin. Gerekli sınır, yöntem ve KKD\'yi değerlendirme sonucuna göre belirleyin; tek tip kalori değeri atamayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-092', 'bolum' => 'Trafo', 'faaliyet' => 'Hücre iç ark koruması', 'tehlike' => 'Kapak veya basınç tahliye yolunun uygunsuzluğu', 'risk' => 'Sıcak gaz ve parça fırlaması', 'mevcut_onlem' => NULL, 'oneri' => 'Hücrenin üretici şartlarına uygun kurulumunu, kapaklarını ve tahliye düzenini doğrulayın. Tahliye yönünü personel/kaçış yolundan uzak tutun. Kapak açık manevra veya tasarım dışı delik açma yaptırmayın; iç ark sınıfının sınırlarını inceleyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-093', 'bolum' => 'Trafo', 'faaliyet' => 'Mekanik/elektriksel kilitlemeler', 'tehlike' => 'Kilidin zorlanması veya baypas edilmesi', 'risk' => 'Canlı hücreye erişim ve kısa devre', 'mevcut_onlem' => NULL, 'oneri' => 'Kesici, ayırıcı, toprak ayırıcısı ve kapı kilitlemelerini üretici fonksiyonuna göre test edin. Kilidi zorlayarak manevra yaptırmayın. Arızalı kilitlemede hücreyi güvenli şekilde kullanım dışı bırakın; değişiklik sonrası doğrulayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-094', 'bolum' => 'Trafo', 'faaliyet' => 'Uzaktan/otomatik kumanda', 'tehlike' => 'SCADA veya otomasyonla beklenmeyen kapanma', 'risk' => 'Bakım personelinin elektriğe maruziyeti', 'mevcut_onlem' => NULL, 'oneri' => 'İzolasyon sırasında uzaktan, otomatik ve yerel tüm kumandaları onaylı prosedürle kontrol altına alın. Yetki ve komut kayıtlarını yönetin. Yazılımda yerel seçmek veya uyarı koymak fiziksel güvenli izolasyonun yerine geçmesin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8, 10–11; Ek I–II; Ek III elektrik tesisatları ve transformatörler (ilgili işlem) | Makina Emniyeti Yön.: Doğrudan uygulanmaz: YG transformatörü/şaltı Makina Emniyeti kapsamı dışında; elektrik mevzuatı esas. | Standart/teknik: IEC 60076 serisi; IEC 61936-1:2021; EN 50110-1; üretici/proje; ilgili elektrik mevzuatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
